package lk.ac.sliit.ridelink.driver.infrastructure.persistence.mapper;
import lk.ac.sliit.ridelink.driver.domain.model.DriverProfile; import lk.ac.sliit.ridelink.driver.infrastructure.persistence.entity.DriverProfileJpaEntity;
public final class DriverPersistenceMapper { private DriverPersistenceMapper(){} public static DriverProfileJpaEntity entity(DriverProfile d){return new DriverProfileJpaEntity(d.getId(),d.getAccountId(),d.getLicenceNumber(),d.getAvailabilityStatus(),d.getServiceArea(),d.serviceAreaKey(),d.getCurrentLatitude(),d.getCurrentLongitude(),d.getAvailableSince(),d.getCurrentRideId(),d.getCreatedAt(),d.getUpdatedAt());} public static DriverProfile domain(DriverProfileJpaEntity e){return new DriverProfile(e.getId(),e.getAccountId(),e.getLicenceNumber(),e.getAvailabilityStatus(),e.getServiceArea(),e.getCurrentLatitude(),e.getCurrentLongitude(),e.getAvailableSince(),e.getCurrentRideId(),e.getCreatedAt(),e.getUpdatedAt());} }
